mkdir -p /workspace/probes && cat > /workspace/tools/cli.mjs <<'EOF'
// Direct argv probe harness for /workspace/dataset/test16_executable
// Usage: node cli.mjs --file cases.json   where cases.json = [ {name, argv:[...]} , ... ]  or [ [argv...], ... ]
import { spawnSync } from 'node:child_process';
import { readFileSync } from 'node:fs';

const EXE = '/workspace/dataset/test16_executable';

function run(argv, opts = {}) {
  const r = spawnSync(EXE, argv, { encoding: 'utf8', maxBuffer: 1 << 28, ...opts });
  return {
    code: r.status,
    signal: r.signal ?? null,
    stdout: r.stdout ?? '',
    stderr: r.stderr ?? '',
  };
}

const argv = process.argv.slice(2);
if (argv[0] === '--file') {
  const list = JSON.parse(readFileSync(argv[1], 'utf8'));
  const out = list.map((c) => {
    const a = Array.isArray(c) ? c : c.argv;
    const name = Array.isArray(c) ? null : (c.name ?? null);
    const env = Array.isArray(c) ? undefined : c.env;
    const r = run(a, env ? { env: { ...process.env, ...env } } : {});
    return { name, argv: a, code: r.code, signal: r.signal, stdout: r.stdout, stderr: r.stderr };
  });
  process.stdout.write(JSON.stringify(out, null, 1) + '\n');
} else {
  const r = run(argv);
  process.stdout.write(JSON.stringify(r, null, 1) + '\n');
}
EOF
node /workspace/tools/cli.mjs --a A --b B --c C --d D --e E | head -50

cat > /workspace/tools/cli.mjs <<'EOF'
import { spawnSync } from 'node:child_process';
import { readFileSync } from 'node:fs';

const EXE = '/workspace/dataset/test16_executable';

function run(c) {
  const a = Array.isArray(c) ? c : c.argv;
  const opts = { encoding: 'buffer', maxBuffer: 1 << 28 };
  if (!Array.isArray(c)) {
    if (c.argv0) opts.argv0 = c.argv0;
    if (c.env) opts.env = c.envReplace ? c.env : { ...process.env, ...c.env };
    if (c.cwd) opts.cwd = c.cwd;
  }
  const exe = (!Array.isArray(c) && c.exe) ? c.exe : EXE;
  const r = spawnSync(exe, a, opts);
  const so = r.stdout ?? Buffer.alloc(0);
  const se = r.stderr ?? Buffer.alloc(0);
  return {
    name: Array.isArray(c) ? null : (c.name ?? null),
    argv: a,
    code: r.status, signal: r.signal ?? null,
    stdout: so.toString('utf8'), stderr: se.toString('utf8'),
    stdout_len: so.length, stderr_len: se.length,
    err: r.error ? String(r.error.message) : undefined,
  };
}

const argv = process.argv.slice(2);
if (argv[0] === '--file') {
  const list = JSON.parse(readFileSync(argv[1], 'utf8'));
  process.stdout.write(JSON.stringify(list.map(run), null, 1) + '\n');
} else {
  process.stdout.write(JSON.stringify(run(argv), null, 1) + '\n');
}
EOF
